import{_ as i,o as e,c as t,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Performance Meeting 2018-10-11","description":"","frontmatter":{"title":"Ceph Performance Meeting 2018-10-11","date":"2018-10-11T00:00:00.000Z","updated":"2018-10-18T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","两阶段提交","缓存机制"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Ceph_Performance_Meeting_2018-10-11.md","filePath":"posts/2018/Ceph_Performance_Meeting_2018-10-11.md","lastUpdated":1780460162000}'),r={name:"posts/2018/Ceph_Performance_Meeting_2018-10-11.md"};function o(n,l,p,s,u,d){return e(),t("div",null,[...l[0]||(l[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2018年10月11日</p><p><strong>参会人员</strong>： Radek、Adam、Braddock、Adam（视频会议字幕翻译及总结人员）、Matt、Kyle、Nick</p><p><strong>会议主题</strong>： Ceph分布式存储项目进展及讨论</p><p><strong>会议内容</strong>：</p><p><strong>一、PRS进展</strong></p><ul><li>Radek和Adam正在开发两阶段提交机制和编码相关功能，预计将大幅提升性能，减少缓冲区指针的错误使用。</li><li>该机制将消除整数字段中的跳转检查，这对于性能调优尤为重要，尤其是在客户端动态链接的情况下。</li><li>探讨了优化缓冲区列表的几种方法，包括： <ul><li>将缓冲区指针内联化，并使用编译器去除死代码。</li><li>使用连续填充器将小缓冲区指针编码到更大的对象中。</li><li>在编译时使用<code>restrict</code>关键字，以允许编译器进行死代码消除。</li></ul></li></ul><p><strong>二、其他PR讨论</strong></p><ul><li>讨论了多个PR，包括API更改、删除不再使用的请求重定向指令、优化缓冲区列表等。</li><li>重点讨论了以下PR： <ul><li>将缓冲区指针与缓冲区进行生命周期连接，并允许不同的缓冲区指针引用相同的缓冲区。</li><li>使用 intrusive 构造来管理内存，并允许在单个内存块中分配数据封装的缓冲区行、缓冲区指针和缓冲区指针。</li></ul></li></ul><p><strong>三、分布式数据缓存PR</strong></p><ul><li>讨论了用于Radius GW的分布式数据缓存PR。</li><li>该PR使用关联缓存结构，并与其他缓存机制结合，以实现更好的性能和一致性。</li><li>该PR主要应用于处理Hadoop、Spark和Linux工作负载的多租户环境。</li></ul><p><strong>四、Numa节点优化</strong></p><ul><li>讨论了Numa节点优化，以及如何将进程或线程绑定到特定的Numa节点以提高性能。</li><li>讨论了以下方法： <ul><li>在Crush Map中添加Numa节点级别，以允许OSD智能地映射到正确的Numa节点。</li><li>使用系统控制命令将进程绑定到特定的CPU核心。</li><li>与硬件供应商合作，以优化Numa节点布局。</li></ul></li></ul><p><strong>五、其他事项</strong></p><ul><li>讨论了以下事项： <ul><li>Nick关于缓存模式交换的PR。</li><li>Nick关于延迟写入的PR。</li><li>Nick关于缓存命中集的PR。</li></ul></li></ul><p><strong>行动计划</strong>：</p><ul><li>Radek和Adam继续开发两阶段提交机制和编码相关功能。</li><li>审查和合并其他PR。</li><li>讨论分布式数据缓存PR的进一步优化。</li><li>与硬件供应商合作，以优化Numa节点布局。</li><li>回复Nick关于缓存模式交换、延迟写入和缓存命中集的PR。</li></ul><p><strong>总结</strong>：</p><p>本次会议讨论了Ceph分布式存储项目的多个方面，包括PRS进展、其他PR讨论、分布式数据缓存PR、Numa节点优化以及其他事项。会议确定了下一步行动计划，以推动Ceph项目的进展。</p>',19)])])}const g=i(r,[["render",o]]);export{c as __pageData,g as default};
